class Solution {
  public long countIntersectingIntervals(int[][] intervals) {
    int n = intervals.length;
    long[] ends = new long[n];
    for (int i = 0; i < n; i++) ends[i] = intervals[i][1];
    java.util.Arrays.sort(ends);
    long apart = 0;
    for (int[] iv : intervals) {
      int lo = 0, hi = n;
      while (lo < hi) {
        int mid = (lo + hi) >>> 1;
        if (ends[mid] < iv[0]) lo = mid + 1;
        else hi = mid;
      }
      apart += lo;
    }
    return (long) n * (n - 1) / 2 - apart;
  }
}
